package com.securebiz.sales.service;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.securebiz.audit.repository.ActivityLogRepository;import com.securebiz.inventory.repository.InventoryRepository;import com.securebiz.inventory.repository.StockOperationRepository;import com.securebiz.sales.api.SalesDtos.*;import com.securebiz.sales.repository.SalesRepository;import com.securebiz.shared.api.BusinessException;import com.securebiz.shared.security.CurrentActor;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import com.securebiz.shared.api.PageResponse;
@Service public class SalesService{private final SalesRepository sales;private final InventoryRepository inventory;private final StockOperationRepository stock;private final ActivityLogRepository audit;private final ObjectMapper json;public SalesService(SalesRepository sales,InventoryRepository inventory,StockOperationRepository stock,ActivityLogRepository audit,ObjectMapper json){this.sales=sales;this.inventory=inventory;this.stock=stock;this.audit=audit;this.json=json;}
 @PreAuthorize("hasAuthority('customer.view')")@Transactional(readOnly=true)public PageResponse<CustomerResponse> customers(String q,int page,int size,String sort){String search=q==null?"":q.strip();return PageResponse.of(sales.customers(search,size,(long)page*size,sort),page,size,sales.countCustomers(search));}
 @PreAuthorize("hasAuthority('customer.view')")@Transactional(readOnly=true)public CustomerHistory customerHistory(UUID id){var customer=sales.findCustomer(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"CUSTOMER_NOT_FOUND","Customer not found"));var orders=sales.ordersByCustomer(id);return new CustomerHistory(customer,orders.size(),sales.customerNetSpending(id),orders);}
 @PreAuthorize("hasAuthority('customer.manage')")@Transactional public CustomerResponse createCustomer(CustomerRequest r){UUID id=UUID.randomUUID(),actor=CurrentActor.userId();try{var x=sales.createCustomer(id,r);audit.appendMutation(actor,"CUSTOMER_CREATE","sales","customer",id,"null",write(x));return x;}catch(DataIntegrityViolationException e){throw conflict("CUSTOMER_CONFLICT","Customer code is already used");}}
 @PreAuthorize("hasAuthority('order.view')")@Transactional(readOnly=true)public PageResponse<OrderResponse> orders(String status,int page,int size,String sort){String normalized=status==null?"":status.strip().toUpperCase();return PageResponse.of(sales.orders(normalized,size,(long)page*size,sort),page,size,sales.countOrders(normalized));}
 @PreAuthorize("hasAuthority('order.view')")@Transactional(readOnly=true)public OrderResponse order(UUID id){return sales.order(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Order not found"));}
 @PreAuthorize("hasAuthority('order.create')")@Transactional public OrderResponse checkout(CheckoutRequest r){UUID actor=CurrentActor.userId();String requestJson=write(r),hash=sha256(requestJson);UUID idem=UUID.randomUUID();if(!sales.claimIdempotency(idem,actor,r.idempotencyKey(),hash)){var state=sales.idempotency(actor,r.idempotencyKey()).orElseThrow();if(!state.requestHash().equals(hash))throw conflict("IDEMPOTENCY_KEY_REUSED","Idempotency key was used for another request");if("COMPLETED".equals(state.status()))return order(state.resourceId());throw conflict("CHECKOUT_IN_PROGRESS","Checkout with this key is in progress");}
  Map<UUID,CheckoutItem> requested=new HashMap<>();for(var i:r.items())if(requested.put(i.variantId(),i)!=null)throw invalid("DUPLICATE_ORDER_VARIANT","A SKU may appear once");List<UUID> ids=requested.keySet().stream().sorted().toList();var variants=sales.saleVariants(ids);if(variants.size()!=ids.size()||variants.stream().anyMatch(v->!"ACTIVE".equals(v.status())))throw invalid("INVALID_ORDER_VARIANT","One or more SKUs are invalid or inactive");if(variants.stream().anyMatch(v->!"VND".equals(v.currency())))throw invalid("MIXED_CURRENCY_UNSUPPORTED","Checkout currently requires VND variants");BigDecimal subtotal=variants.stream().map(v->v.price().multiply(requested.get(v.id()).quantity())).reduce(BigDecimal.ZERO,BigDecimal::add);if(r.discountTotal().compareTo(subtotal)>0)throw invalid("DISCOUNT_EXCEEDS_SUBTOTAL","Discount cannot exceed subtotal");BigDecimal total=subtotal.subtract(r.discountTotal());if(total.signum()<=0)throw invalid("NON_POSITIVE_ORDER_TOTAL","Order total must be positive");
  UUID order=UUID.randomUUID(),tx=UUID.randomUUID();String orderNo="ORD-"+shortId(order);sales.createOrder(order,orderNo,r,actor,subtotal,total);stock.createStockHeader(tx,"SAL-"+shortId(tx),r.warehouseId(),"SALE",actor,"order",order,"Checkout sale");BigDecimal allocated=BigDecimal.ZERO;for(int index=0;index<variants.size();index++){var v=variants.get(index);BigDecimal qty=requested.get(v.id()).quantity();inventory.ensureBalance(r.warehouseId(),v.id());var b=inventory.lockBalance(r.warehouseId(),v.id()).orElseThrow();BigDecimal after=b.quantity().subtract(qty);if(after.signum()<0)throw conflict("INSUFFICIENT_STOCK","Insufficient stock for SKU "+v.sku());BigDecimal discount=index==variants.size()-1?r.discountTotal().subtract(allocated):r.discountTotal().multiply(v.price().multiply(qty)).divide(subtotal,4,RoundingMode.DOWN);allocated=allocated.add(discount);inventory.updateBalance(b.id(),after);stock.createStockItem(tx,v.id(),qty.negate(),b.quantity(),after);sales.createOrderItem(UUID.randomUUID(),order,v,qty,discount);}
  sales.createPayment(UUID.randomUUID(),order,r.paymentMethod(),total,"VND",r.idempotencyKey(),actor);String invoice=sales.createInvoice(UUID.randomUUID(),order,"INV-"+shortId(order),subtotal,r.discountTotal(),total,"VND");sales.outbox(UUID.randomUUID(),order,"{\"orderId\":\""+order+"\",\"event\":\"ORDER_COMPLETED\"}");sales.completeIdempotency(actor,r.idempotencyKey(),order);var result=sales.order(order).orElseThrow();audit.appendMutation(actor,"ORDER_CREATE","sales","order",order,"null",write(result));return result;}
 private String write(Object o){try{return json.writeValueAsString(o);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private String sha256(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private String shortId(UUID id){return id.toString().substring(0,8).toUpperCase();}private BusinessException invalid(String c,String m){return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,c,m);}private BusinessException conflict(String c,String m){return new BusinessException(HttpStatus.CONFLICT,c,m);}
}
